# Surah Al-Ma'ida (chapter 5) — part 7: ayat 61-70 (IDs 730-739)
SURAH = 5

ENTRIES = {
730: (
"اور جب وہ تمہارے پاس آتے ہیں تو کہتے ہیں: ہم ایمان لائے — حالانکہ وہ کفر کے ساتھ داخل ہوئے اور اسی کے ساتھ نکل گئے — اور اللہ بہتر جانتا ہے جو وہ چھپاتے ہیں",
"""۱۔ منافق — زبانی ایمان، مگر دل کا کفر۔
۲۔ ’’وَإِذَا جَاءُوكُمْ قَالُوا آمَنَّا وَقَدْ دَخَلُوا بِالْكُفْرِ وَهُمْ قَدْ خَرَجُوا بِهِ‘‘ — اور جب وہ تمہارے پاس آتے ہیں تو کہتے ہیں: ہم ایمان لائے — حالانکہ وہ کفر کے ساتھ داخل ہوئے اور اسی کے ساتھ نکل گئے — یعنی زبان سے ایمان، مگر دل کفر سے بھرے رہتے ہیں۔
۳۔ ’’وَاللّٰہُ أَعْلَمُ بِمَا كَانُوا يَكْتُمُونَ‘‘ — اور اللہ بہتر جانتا ہے جو وہ چھپاتے ہیں — یعنی ان کا دہرا چہرہ اللہ پر واضح ہے۔
۴۔ عملی سبق: اپنے دل کا آئینہ صاف رکھو؛ ریا کاری سے بچو۔"""
),
731: (
"اور آپ ان میں سے اکثر کو دیکھیں گے کہ گناہ اور زیادتی اور حرام (مال) کے کھانے میں تیز قدم اٹھا رہے ہیں — بے شک وہ برا کر رہے ہیں",
"""۱۔ حرام کا کھانا — یہود کی عادت۔
۲۔ ’’وَتَرَىٰ كَثِيرًا مِّنْهُمْ يُسَارِعُونَ فِي الْإِثْمِ وَالْعُدْوَانِ وَأَكْلِهِمُ السُّحْتَ‘‘ — اور آپ ان میں سے اکثر کو دیکھیں گے کہ گناہ اور زیادتی اور حرام (مال) کے کھانے میں تیز قدم اٹھا رہے ہیں — یعنی یہود رشوت اور حرام آمدنی کے عادی تھے۔
۳۔ ’’لَبِئْسَ مَا كَانُوا يَعْمَلُونَ‘‘ — بے شک وہ برا کر رہے ہیں — یعنی ان کا عمل نہایت برا ہے۔
۴۔ عملی سبق: حرام مال سے مکمل پرہیز کرو؛ گناہ میں سبقت مت کرو۔"""
),
732: (
"(انہیں) کیوں نہیں روکتے اللہ والے اور علماء — گناہ کی بات اور حرام (مال) کے کھانے سے — بے شک یہ بہت برا کر رہے ہیں",
"""۱۔ علماء کی خاموشی — بڑا قصور۔
۲۔ ’’لَوْلَا يَنْهَاهُمُ الرَّبَّانِيُّونَ وَالْأَحْبَارُ عَن قَوْلِهِمُ الْإِثْمَ وَأَكْلِهِمُ السُّحْتَ‘‘ — (انہیں) کیوں نہیں روکتے اللہ والے اور علماء — گناہ کی بات اور حرام (مال) کے کھانے سے — یعنی علماء کی خاموشی گناہ کا معاونت ہے۔
۳۔ ’’لَبِئْسَ مَا كَانُوا يَصْنَعُونَ‘‘ — بے شک یہ بہت برا کر رہے ہیں — یعنی دین کے سرپرست بھی حصہ ڈال چکے ہیں۔
۴۔ عملی سبق: اچھی بات کہنا علماء اور ہر مسلمان پر لازم ہے؛ برائی کے سامنے خاموش مت رہو۔"""
),
733: (
"اور یہود نے کہا: اللہ کا ہاتھ بندھا ہوا ہے — ان کے ہاتھ باندھ دیے جائیں اور ان پر لعنت کی گئی — اس بات کی وجہ سے جو انہوں نے کہا — بلکہ اس کے دونوں ہاتھ کھلے ہوئے ہیں — وہ جس طرح چاہے خرچ کرتا ہے — اور — جو آپ کی طرف آپ کے رب سے نازل کیا گیا ہے — (وہ) ان میں سے اکثر کو — ضرور — سرکشی اور کفر میں زیادہ کرے گا — اور ہم نے قیامت تک ان کے درمیان دشمنی اور کینے کی آگ بھڑکا دی — جب بھی وہ جنگ کے لیے کوئی آگ بھڑکائیں — اللہ اسے بجھا دیتا ہے — اور وہ زمین میں فساد پھیلانے کی کوشش کرتے ہیں — اور اللہ فساد پھیلانے والوں سے محبت نہیں کرتا",
"""۱۔ یہود کا الزام — اللہ کا ہاتھ بندھا ہوا۔
۲۔ ’’وَقَالَتِ الْيَهُودُ يَدُ اللّٰہِ مَغْلُولَۃٌ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا بِمَا قَالُوا‘‘ — اور یہود نے کہا: اللہ کا ہاتھ بندھا ہوا ہے — ان کے ہاتھ باندھ دیے جائیں اور ان پر لعنت کی گئی — اس بات کی وجہ سے جو انہوں نے کہا — یعنی یہود نے بخل کا الزام لگایا — حالانکہ وہ بخیل تھے۔
۳۔ ’’بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنفِقُ كَيْفَ يَشَاءُ‘‘ — بلکہ اس کے دونوں ہاتھ کھلے ہوئے ہیں — وہ جس طرح چاہے خرچ کرتا ہے — یعنی اللہ کی نعمتیں بے حساب ہیں۔
۴۔ ’’وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا‘‘ — اور — جو آپ کی طرف آپ کے رب سے نازل کیا گیا ہے — (وہ) ان میں سے اکثر کو — ضرور — سرکشی اور کفر میں زیادہ کرے گا — یعنی قرآن سن کر ان کا کفر بڑھتا ہے۔
۵۔ ’’وَأَلْقَيْنَا بَيْنَهُمُ الْعَدَاوَۃَ وَالْبَغْضَاءَ إِلَىٰ يَوْمِ الْقِيَامَۃِ‘‘ — اور ہم نے قیامت تک ان کے درمیان دشمنی اور کینے کی آگ بھڑکا دی۔
۶۔ ’’كُلَّمَا أَوْقَدُوا نَارًا لِّلْحَرْبِ أَطْفَأَهَا اللّٰہُ‘‘ — جب بھی وہ جنگ کے لیے کوئی آگ بھڑکائیں — اللہ اسے بجھا دیتا ہے — یعنی ان کی جنگی کوششیں ناکام ہوتی ہیں۔
۷۔ ’’وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا وَاللّٰہُ لَا يُحِبُّ الْمُفْسِدِينَ‘‘ — اور وہ زمین میں فساد پھیلانے کی کوشش کرتے ہیں — اور اللہ فساد پھیلانے والوں سے محبت نہیں کرتا۔
۸۔ عملی سبق: اللہ کی فیاضی کو تسلیم کرو؛ فساد اور بخل سے بچو۔"""
),
734: (
"اور اگر اہلِ کتاب ایمان لائے اور ڈرتے تو ہم ان کے گناہ معاف کر دیتے اور انہیں نعمتوں والی جنتوں میں داخل کرتے",
"""۱۔ اہلِ کتاب — ایمان اور تقویٰ اختیار کریں تو مغفرت۔
۲۔ ’’وَلَوْ أَنَّ أَهْلَ الْكِتَابِ آمَنُوا وَاتَّقَوْا لَكَفَّرْنَا عَنْهُمْ سَيِّئَاتِهِمْ وَلَأَدْخَلْنَاهُمْ جَنَّاتِ النَّعِيمِ‘‘ — اور اگر اہلِ کتاب ایمان لائے اور ڈرتے تو ہم ان کے گناہ معاف کر دیتے اور انہیں نعمتوں والی جنتوں میں داخل کرتے — یعنی دروازہ ہمیشہ کھلا ہے۔
۳۔ عملی سبق: ایمان اور تقویٰ اختیار کرو؛ اللہ کے دروازے ہمیشہ کھلے ہیں۔"""
),
735: (
"اور اگر وہ تورات اور انجیل — اور جو ان کے رب کی طرف سے ان پر نازل کیا گیا ہے — قائم کرتے تو انہیں — ان کے اوپر سے اور ان کے پاؤں کے نیچے سے — (اچھے کھانے) ملتے — ان میں سے ایک اعتدال پسند جماعت ہے — اور ان میں سے اکثر — (ان کا عمل) برا ہے جو وہ کر رہے ہیں",
"""۱۔ تورات اور انجیل کے مطابق عمل — دنیا و آخرت میں رزق۔
۲۔ ’’وَلَوْ أَنَّهُمْ أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ‘‘ — اور اگر وہ تورات اور انجیل — اور جو ان کے رب کی طرف سے ان پر نازل کیا گیا ہے — قائم کرتے — یعنی اگر وہ اپنی کتاب کے احکام پر عمل کرتے۔
۳۔ ’’لَأَكَلُوا مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم‘‘ — تو انہیں — ان کے اوپر سے اور ان کے پاؤں کے نیچے سے — (اچھے کھانے) ملتے — یعنی آسمان سے بارش اور زمین سے پیداوار — رزق اسی طرح ملتا ہے۔
۴۔ ’’مِّنْهُمْ أُمَّۃٌ مُّقْتَصِدَۃٌ وَكَثِيرٌ مِّنْهُمْ سَاءَ مَا يَعْمَلُونَ‘‘ — ان میں سے ایک اعتدال پسند جماعت ہے — اور ان میں سے اکثر — (ان کا عمل) برا ہے جو وہ کر رہے ہیں — یعنی ان سب میں چند صالح لوگ بھی ہیں۔
۵۔ عملی سبق: اللہ کی کتاب کے احکام پر عمل کرو؛ رزق اللہ دیتا ہے۔"""
),
736: (
"اے رسول! آپ — جو آپ کی طرف آپ کے رب سے نازل کیا گیا ہے — پہنچا دیں — اور اگر آپ نے ایسا نہ کیا تو اس کی رسالت (دین کا پیغام) نہیں پہنچایا — اور اللہ آپ کو لوگوں سے محفوظ رکھے گا — بے شک اللہ کافروں کو ہدایت نہیں دیتا",
"""۱۔ نبی ﷺ کا پیغام پہنچانا — ذمہ داری۔
۲۔ ’’يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ‘‘ — اے رسول! آپ — جو آپ کی طرف آپ کے رب سے نازل کیا گیا ہے — پہنچا دیں — اہل تشیع کے نزدیک یہ آیت ولایتِ علیؑ کے اعلان کے اختتام کے موقع پر نازل ہوئی — جب نبی ﷺ نے حجۃ الوداع کے بعد غدیر خم میں حضرت علی علیہ السلام کو اپنا ولی (جانشین) مقرر فرمایا۔
۳۔ ’’وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُ‘‘ — اور اگر آپ نے ایسا نہ کیا تو اس کی رسالت (دین کا پیغام) نہیں پہنچایا — یعنی اس حکم کو پہنچانا پوری رسالت کے برابر ہے۔
۴۔ ’’وَاللّٰہُ يَعْصِمُكَ مِنَ النَّاسِ إِنَّ اللّٰہَ لَا يَهْدِي الْقَوْمَ الْكَافِرِينَ‘‘ — اور اللہ آپ کو لوگوں سے محفوظ رکھے گا — بے شک اللہ کافروں کو ہدایت نہیں دیتا — یعنی اللہ نے نبی ﷺ کی حفاظت کی ضمانت دی۔
۵۔ عملی سبق: حق کا پیغام پوری طرح پہنچاؤ؛ اللہ کی حفاظت پر بھروسہ رکھو۔"""
),
737: (
"کہہ دیں: اے اہلِ کتاب! تم کسی چیز پر نہیں ہو — یہاں تک کہ تورات، انجیل — اور — جو تمہارے رب کی طرف سے تم پر نازل کیا گیا ہے — قائم کرو — اور — جو آپ کی طرف آپ کے رب سے نازل کیا گیا ہے — (وہ) ان میں سے اکثر کو — ضرور — سرکشی اور کفر میں زیادہ کرے گا — پس تم کافروں پر غمگین نہ ہو",
"""۱۔ اہلِ کتاب — کتاب پر عمل کیے بغیر دین بے سود۔
۲۔ ’’قُلْ يَا أَهْلَ الْكِتَابِ لَسْتُمْ عَلَىٰ شَيْءٍ حَتَّىٰ تُقِيمُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ‘‘ — کہہ دیں: اے اہلِ کتاب! تم کسی چیز پر نہیں ہو — یہاں تک کہ تورات، انجیل — اور — جو تمہارے رب کی طرف سے تم پر نازل کیا گیا ہے — قائم کرو — یعنی صرف دعویٰ کافی نہیں — عمل بھی ضروری ہے۔
۳۔ ’’وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا‘‘ — اور — جو آپ کی طرف آپ کے رب سے نازل کیا گیا ہے — (وہ) ان میں سے اکثر کو — ضرور — سرکشی اور کفر میں زیادہ کرے گا۔
۴۔ ’’فَلَا تَأْسَ عَلَى الْقَوْمِ الْكَافِرِينَ‘‘ — پس تم کافروں پر غمگین نہ ہو — یعنی کافروں کی سرکشی کا غم نہ کرو۔
۵۔ عملی سبق: دین پر صرف ایمان کافی نہیں — اس پر عمل بھی ضروری ہے۔"""
),
738: (
"بے شک جو لوگ ایمان لائے — اور جو یہود ہیں — اور صائبین اور نصاریٰ — جو کوئی اللہ اور آخرت کے دن پر ایمان لائے اور نیک عمل کرے — تو ان پر کوئی خوف نہیں — اور نہ وہ غمگین ہوں گے",
"""۱۔ حقیقی نجات — ایمان اور نیک عمل۔
۲۔ ’’إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَادُوا وَالصَّابِئُونَ وَالنَّصَارَىٰ مَنْ آمَنَ بِاللّٰہِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَالِحًا‘‘ — بے شک جو لوگ ایمان لائے — اور جو یہود ہیں — اور صائبین اور نصاریٰ — جو کوئی اللہ اور آخرت کے دن پر ایمان لائے اور نیک عمل کرے — یعنی تمام باایمان لوگوں میں سے — نجات ان کی ہے جو اللہ اور آخرت پر ایمان لائیں اور نیک عمل کریں۔
۳۔ ’’فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ‘‘ — تو ان پر کوئی خوف نہیں — اور نہ وہ غمگین ہوں گے — یعنی قیامت کے دن کی کوئی فکر نہیں۔
۴۔ عملی سبق: اللہ اور آخرت پر ایمان اور نیک عمل کرو؛ نجات کی راہ یہی ہے۔"""
),
739: (
"تحقیق ہم نے بنی اسرائیل سے پختہ عہد لیا اور ان کے پاس رسول بھیجے — جب بھی کوئی رسول ان کے پاس — ان کی خواہش کے خلاف — آیا — تو انہوں نے ایک گروہ کو جھٹلایا اور ایک گروہ کو قتل کر دیتے تھے",
"""۱۔ بنی اسرائیل کا سلسلہ — رسولوں کو جھٹلایا یا قتل کیا۔
۲۔ ’’لَقَدْ أَخَذْنَا مِيثَاقَ بَنِي إِسْرَائِيلَ وَأَرْسَلْنَا إِلَيْهِمْ رُسُلًا‘‘ — تحقیق ہم نے بنی اسرائیل سے پختہ عہد لیا اور ان کے پاس رسول بھیجے۔
۳۔ ’’كُلَّمَا جَاءَهُمْ رَسُولٌ بِمَا لَا تَهْوَىٰ أَنفُسُهُمْ فَرِيقًا كَذَّبُوا وَفَرِيقًا يَقْتُلُونَ‘‘ — جب بھی کوئی رسول ان کے پاس — ان کی خواہش کے خلاف — آیا — تو انہوں نے ایک گروہ کو جھٹلایا اور ایک گروہ کو قتل کر دیتے تھے — یعنی رسولوں کو خواہشات کے مطابق رد کیا جاتا یا قتل کیا جاتا تھا۔
۴۔ عملی سبق: اپنی خواہشات کے مطابق دین میں ردوبدل نہ کرو؛ رسولوں کی اطاعت کرو۔"""
),
}
